// Parse Ollama's response. Its `response` field is a string we asked the model
// to format as JSON. Sometimes the model wraps it in ```json fences anyway.

const raw = $input.first().json.response ?? '';
const cleaned = raw.trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  parsed = { raw_response: raw, parse_error: err.message };
}

const imagePath = $('Set Image Path').first().json.imagePath;

const result = {
  source_image: imagePath,
  model: 'llama3.2-vision',
  analyzed_at: new Date().toISOString(),
  ...parsed,
};

return [{
  json: result,
  binary: {
    data: {
      data: Buffer.from(JSON.stringify(result, null, 2)).toString('base64'),
      mimeType: 'application/json',
      fileName: imagePath.split('/').pop() + '.json',
      fileExtension: 'json',
    },
  },
}];

// n8n stores binary data either inline (base64 in .data) or on the filesystem
// (with .id pointing to the file). getBinaryDataBuffer handles both cases and
// always returns the actual bytes.

const item = $input.first();
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64Image = buffer.toString('base64');

if (!base64Image) {
  throw new Error('Could not extract image bytes from binary data.');
}

return [{
  json: {
    model: 'llama3.2-vision',
    prompt: 'Analyze this image and respond with ONLY a JSON object (no markdown, no code fences) with these fields: title (3-7 word title), description (2-3 sentences), tags (array of 5-10 keywords), scene_type (one of: portrait, landscape, indoor, food, document, screenshot, object, other).',
    images: [base64Image],
    stream: false,
  },
}];
